r i min blok.', 'I write notes in my notepad.'), ('tidsskrift', 'word', '0566a838-8839-5e36-96de-4d4def480d04', 1, 'noun', 'et', 'journal, periodical', 'Jeg læser et videnskabeligt tidsskrift.', 'I read a scientific journal.'), ('indgang', 'word', '229bcc24-3ab5-582f-86e9-4c5ffbec89c1', 1, 'noun', 'en', 'entrance', 'Hvor er indgangen til bygningen?', 'Where is the entrance to the building?'), ('indgreb', 'word', '1168ff33-381c-5575-baae-c0e3c27d88c9', 1, 'noun', 'et', 'intervention', 'Det kræver et politisk indgreb.', 'It requires a political intervention.'), ('indgreb', 'word', 'e006fec4-2d20-55ab-8c30-c6bffb416597', 2, 'noun', 'et', 'procedure (surgical)', 'Lægen foretog et lille indgreb.', 'The doctor performed a minor procedure.'), ('udstyre', 'word', '20bda643-821a-59da-a5df-1611f9685541', 1, 'verb', null, 'to equip', 'Vi skal udstyre kontoret med nye computere.', 'We must equip the office with new computers.'), ('fascinere', 'word', 'cb9630a3-d64e-5d8d-8bd2-c7fb2f8df779', 1, 'verb', null, 'to fascinate', 'Historien fascinerer mig.', 'The story fascinates me.'), ('ambassade', 'word', '287c3e3f-bf29-531a-a38e-cb0636a52a1a', 1, 'noun', 'en', 'embassy', 'Jeg skal besøge den danske ambassade.', 'I have to visit the Danish embassy.'), ('indkomst', 'word', 'b47656fa-493a-589a-a661-791f97d600d7', 1, 'noun', 'en', 'income', 'Hun har en høj indkomst.', 'She has a high income.'), ('hvori', 'word', 'c03f0f5c-ac62-5f7c-b6e4-48d412b43c85', 1, 'adverb', null, 'in which', 'Det er et rum, hvori man kan slappe af.', 'It is a room in which one can relax.'), ('bind', 'word', 'e6476a99-ff82-56b2-bde9-70b892256d3d', 1, 'noun', 'et', 'volume (of a book)', 'Bogen er udgivet i tre bind.', 'The book is published in three volumes.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
